const o = phi.observe();
const want = ["Under $25,000","Under 30,000 miles","Apple CarPlay","Adaptive Cruise Control","Blindspot Sensors"];
const res = [];
for (const w of want) {
  const n = o.nodes.find(x => x.name && x.name.startsWith(w));
  if (!n) { res.push(w + ": NOT FOUND"); continue; }
  const r = phi.click(n.ref);
  res.push(w + " -> navigated:" + r.navigated + " changed:" + JSON.stringify(r.changed || []).slice(0,200));
  phi.sleep(1500);
}
phi.waitForNetworkIdle({ idleMs: 1000, timeoutMs: 15000 });
const o2 = phi.observe();
return { url: o2.url, res, text: o2.text.slice(0, 1600), nodes: o2.nodes.slice(0, 60).map(n => `${n.ref} ${n.role} ${n.name}`) };

const want = ["Under $25,000 (","Under 30,000 miles (","Apple CarPlay (","Adaptive Cruise Control (","Blindspot Sensors ("];
