const log = [];
let o = phi.observe();
const banner = o.nodes.find(n => n.name === "Close banner");
if (banner) { try { phi.click(banner.ref); log.push("banner closed"); phi.sleep(800); } catch(e) { log.push("banner err " + String(e).slice(0,120)); } }

const wants = ["Apple CarPlay", "Adaptive Cruise Control", "Blindspot Sensors"];
for (const w of wants) {
  let done = false;
  for (let attempt = 0; attempt < 3 && !done; attempt++) {
    const oi = phi.observe();
    const n = oi.nodes.find(x => x.name && x.name.startsWith(w) && /button|checkbox|switch|option/.test(x.role));
    if (!n) { log.push(w + ": not found attempt " + attempt); phi.scroll({ dy: 300 }); phi.sleep(600); continue; }
    try {
      const r = phi.click(n.ref);
      phi.waitForNetworkIdle({ idleMs: 1200, timeoutMs: 15000 });
      phi.sleep(700);
      log.push(w + " clicked (" + n.name + ") nav:" + r.navigated);
      done = true;
    } catch (e) {
      log.push(w + " click err: " + String(e).slice(0, 140));
      phi.scroll({ dy: 200, target: undefined });
      phi.sleep(800);
    }
  }
}
phi.waitForNetworkIdle({ idleMs: 1500, timeoutMs: 20000 });
const o2 = phi.observe();
return { url: o2.url, log, text: o2.text.slice(0, 1200), nodes: o2.nodes.slice(0, 40).map(n => `${n.ref} ${n.role} ${n.name}`) };

