const log = [];
const wants = ["Apple CarPlay", "Adaptive Cruise Control", "Blindspot Sensors"];
for (const w of wants) {
  let oi = phi.observe();
  let n = oi.nodes.find(x => x.name && x.name.startsWith(w) && x.role === "button");
  if (!n) { log.push(w + ": no button"); continue; }
  try {
    const r = phi.click(n.ref);
    log.push(w + " clicked -> nav:" + r.navigated);
  } catch (e) { log.push(w + " err " + String(e).slice(0, 120)); continue; }
  phi.waitForNetworkIdle({ idleMs: 1200, timeoutMs: 15000 });
  phi.sleep(1200);
  // dismiss any nudge modal
  const m = phi.query("[class*='SaveSearchNudgeModal_overlay']", { limit: 3 });
  if (m.total > 0) { phi.press("Escape"); phi.sleep(500); log.push("dismissed modal"); }
  const after = phi.observe();
  const applied = after.nodes.filter(x => x.name && /Remove .*filter/.test(x.name)).map(x => x.name);
  log.push("applied: " + applied.join(" | "));
}
const o = phi.observe();
const feats = o.nodes.filter(x => /Apple CarPlay|Adaptive Cruise|Blindspot/.test(x.name || "")).map(n => `${n.ref} ${n.role} ${n.name}`);
return { url: o.url, log, feats, text: o.text.slice(0, 900) };

