const out = {};
phi.press("Escape"); phi.sleep(600);
try { const r = phi.click('[data-testid="sort-button"]'); out.clk = { nav: r.navigated, changed: r.changed }; } catch(e) { out.clkErr = String(e).slice(0,200); }
phi.sleep(1000);
const o = phi.observe({ diff: true });
out.diff = o.nodes.map(n => n.ref + ' ' + n.role + ' ' + n.name).slice(0, 30);
out.tiles = phi.js(() => {
  const as = Array.from(document.querySelectorAll('a[href]')).filter(a => /\/cars\//.test(a.getAttribute('href')) && a.innerText.trim().length > 40);
  const seen = new Set(); const res = [];
  for (const a of as) { const t = a.innerText.replace(/\s+/g,' ').trim(); if (seen.has(t)) continue; seen.add(t); res.push({ href: a.getAttribute('href').split('?')[0], text: t.slice(0,300) }); }
  return res.slice(0, 20);
});
return out;

const o = phi.observe({ viewportOnly: true, maxElements: 120 });
const opts = o.nodes.filter(n => n.role === 'option' || /lowest price/i.test(n.name || ''));
const r = (()=>{ try { return phi.click('option[value], [role="option"]'); } catch(e){ return String(e).slice(0,200); } })();
return { opts: opts.map(n=>n.ref+' '+n.role+' '+n.name), clickRes: typeof r === 'string' ? r : { nav: r.navigated, changed: r.changed } };

phi.press("Escape"); phi.sleep(600);
const data = phi.js(() => {
  const anchors = Array.from(document.querySelectorAll('a[href]'))
    .map(a => ({ href: a.getAttribute('href'), text: (a.innerText || '').replace(/\s+/g,' ').trim() }))
    .filter(a => /\$/.test(a.text) && /mile/i.test(a.text));
  const seen = new Set(); const uniq = [];
  for (const a of anchors) { const k = a.href; if (seen.has(k)) continue; seen.add(k); uniq.push({ href: a.href, text: a.text.slice(0, 400) }); }
  const overlay = Array.from(document.querySelectorAll('div.fixed.inset-0')).map(d => ({ cls: (d.className||'').toString().slice(0,120), rects: d.getBoundingClientRect().height, pe: getComputedStyle(d).pointerEvents, z: getComputedStyle(d).zIndex }));
  const bodyText = (document.body.innerText || '').slice(0, 600);
  return { count: uniq.length, uniq: uniq.slice(0, 30), overlay, bodyText };
});
return data;
